#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BUNDLE_FILE="$ROOT_DIR/dist/app.bundle.js"
MIN_BUNDLE_FILE="$ROOT_DIR/dist/app.bundle.min.js"
TERSER_BIN="$ROOT_DIR/dist/.tools/node_modules/.bin/terser"

APP_SCRIPTS=(
  "lib/theme.js"
  "lib/subsonic.js"
  "lib/textlistbox.js"
  "lib/telemetrylog.js"
  "lib/telemetrypanel.js"
  "lib/filebrowser.js"
  "lib/audioeffects.js"
  "lib/layoutmanager.js"
  "lib/playercontrol.js"
  "lib/userappcontrol.js"
  "lib/sketch.js"
  "lib/playlist.js"
  "lib/progressbar.js"
  "lib/waveform.js"
  "lib/spectrum.js"
  "lib/vumeters.js"
  "lib/vectorscope.js"
  "lib/playinginfo.js"
  "lib/player.js"
  "lib/switch.js"
  "lib/slider_v.js"
  "lib/slider_h.js"
)

: > "$BUNDLE_FILE"
printf "/* Subsonic Neon Deck app bundle. Generated by dist/build-bundle.sh. */\n" >> "$BUNDLE_FILE"
printf "/* p5.js and p5.sound.js are intentionally loaded separately. */\n\n" >> "$BUNDLE_FILE"

for script in "${APP_SCRIPTS[@]}"; do
  printf "\n/* ---- %s ---- */\n" "$script" >> "$BUNDLE_FILE"
  sed '$a\' "$ROOT_DIR/$script" >> "$BUNDLE_FILE"
done

printf "Built %s\n" "$BUNDLE_FILE"

if [ ! -x "$TERSER_BIN" ]; then
  printf "Missing terser. Install it with: npm install --prefix dist/.tools terser\n" >&2
  exit 1
fi

"$TERSER_BIN" "$BUNDLE_FILE" \
  --compress \
  --mangle \
  --output "$MIN_BUNDLE_FILE"
printf "Built %s\n" "$MIN_BUNDLE_FILE"
